initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing a Context Source Registration Subscription (CSRS1)
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations'
        method set to 'POST'
        Create Context Source Registration Request with Content-Type set to 'application/ld+json' and payload set to '${context_source_registration_payload}'
}
